mapper.select:
SELECT tenant_id, sync_run_id AS run_id FROM sys_im_sync_run
WHERE mode = 'APPLY' AND status = 'RUNNING' AND full_snapshot_flag = 1 AND sync_run_id > #{afterId}
ORDER BY sync_run_id LIMIT #{limit}

mapper.update:
UPDATE sys_im_sync_run SET mode = #{row.mode}, snapshot_encrypted = #{row.snapshotEncrypted},
    progress_cursor = #{row.progressCursor}, result_summary = #{row.resultSummary}, status = #{row.status},
    completed_time = #{row.completedTime}, update_by = #{row.updateBy}, update_time = #{row.updateTime}
WHERE tenant_id = #{row.tenantId} AND sync_run_id = #{row.syncRunId} AND config_id = #{row.configId}
    AND config_version = #{row.configVersion} AND snapshot_hash = #{row.snapshotHash} AND full_snapshot_flag = 1
    AND mode = #{mode} AND (progress_cursor = #{cursor} OR (progress_cursor IS NULL AND #{cursor} IS NULL))

UPDATE sys_dept SET parent_id = #{row.parentId}, ancestors = #{row.ancestors}, dept_name = #{row.deptName},
    order_num = #{row.orderNum}, version = version + 1, update_by = #{actor}, update_time = #{now}
WHERE tenant_id = #{row.tenantId} AND dept_id = #{row.deptId} AND version = #{row.version} AND deleted = 0 AND status = '0'

UPDATE sys_im_dept_mapping SET im_dept_name = #{source.name}, im_parent_dept_id = #{source.parentId},
    sync_time = #{now}, version = version + 1, update_by = #{actor}, update_time = #{now}
WHERE tenant_id = #{mapping.tenantId} AND config_id = #{mapping.configId} AND mapping_id = #{mapping.id}
    AND dept_id = #{mapping.departmentId} AND im_dept_id = #{mapping.externalId}
    AND im_type = 'WECOM' AND status = 'ACTIVE' AND version = #{mapping.version}

UPDATE sys_im_user_mapping SET im_name = #{source.name},
    im_avatar = CASE WHEN #{source.avatar.available} THEN #{source.avatar.value} ELSE im_avatar END,
    status = 'ACTIVE', last_sync_time = #{now}, version = version + 1, update_by = #{actor}, update_time = #{now}
WHERE tenant_id = #{mapping.tenantId} AND config_id = #{mapping.configId} AND mapping_id = #{mapping.id}
    AND user_id = #{mapping.userId} AND im_user_id = #{mapping.externalId}
    AND im_type = 'WECOM' AND status = #{mapping.status} AND status IN ('ACTIVE', 'OUT_OF_SCOPE') AND version = #{mapping.version}

UPDATE sys_im_user_mapping SET status = 'OUT_OF_SCOPE', last_sync_time = #{now}, version = version + 1,
    update_by = #{actor}, update_time = #{now}
WHERE tenant_id = #{mapping.tenantId} AND config_id = #{mapping.configId} AND mapping_id = #{mapping.id}
    AND user_id = #{mapping.userId} AND im_user_id = #{mapping.externalId}
    AND im_type = 'WECOM' AND status = 'ACTIVE' AND last_sync_time IS NOT NULL AND version = #{mapping.version}
